class Mobile {
    @Deprecated
    void oldMethod() { }
}

public class Main {

    // Suppress warning for this specific method
    @SuppressWarnings("deprecation")
    void useOldMethod() {
        Mobile m = new Mobile();
        m.oldMethod(); // No warning shown
    }

    // Suppress ALL warnings for this class
    @SuppressWarnings("all")
    void anotherMethod() {
        Mobile m = new Mobile();
        m.oldMethod(); // No warning shown
        int unused = 5; // No "unused" warning either
    }
}

